import type {
  ApparatusType,
  BodyPosition,
  BoxState,
  ClassBlockCategory,
  DifficultyLevel,
  FootbarState,
  HeadrestState,
  PropType,
  SpinalPlane,
  WorkoutTempo,
} from '../types/pilates';

export type AnatomyVisualZone = 'core' | 'glutes' | 'spine' | 'shoulder' | 'lateral' | 'hip';

export type PilatesSchoolTag =
  | 'classical'
  | 'stott'
  | 'balanced-body'
  | 'basi'
  | 'korean-studio'
  | 'fusion-barre'
  | 'fusion-athletic'
  | 'fusion-mobility';

export interface CommonFaultCorrection {
  readonly fault: string;
  readonly fixCue: string;
}

export interface ExerciseAnatomyInsight {
  readonly agonistsKo: readonly string[];
  readonly stabilizersKo: readonly string[];
  readonly benefitsKo: readonly string[];
  readonly springMechanicsKo: string;
  readonly commonFaultsKo: readonly [CommonFaultCorrection, CommonFaultCorrection];
  readonly anatomyVisualZone: AnatomyVisualZone;
}

export interface WorldAtomicSeed {
  readonly slug: string;
  readonly nameKo: string;
  readonly nameEn: string;
  readonly apparatus: ApparatusType;
  readonly props?: readonly PropType[];
  readonly requiredEquipment?: readonly string[];
  readonly blockCategory: ClassBlockCategory;
  readonly spinalPlanes: readonly SpinalPlane[];
  readonly bodyPosition: BodyPosition;
  readonly level: DifficultyLevel;
  readonly defaultDurationMin?: number;
  readonly isUnilateral?: boolean;
  readonly springs: string;
  readonly box?: BoxState;
  readonly footbar?: FootbarState;
  readonly headrest?: HeadrestState;
  readonly targetMuscles: readonly string[];
  readonly breathPattern: string;
  readonly cues: readonly [string, string, string];
  readonly precautions: string;
  readonly layers?: {
    readonly easy: string;
    readonly standard: string;
    readonly hard: string;
  };
  readonly schoolTag: PilatesSchoolTag;
  readonly visualZone: AnatomyVisualZone;
  readonly benefitsKo: readonly string[];
  readonly springMechanicsKo?: string;
  readonly commonFaultsKo?: readonly [CommonFaultCorrection, CommonFaultCorrection];
  readonly tempo?: WorkoutTempo;
  readonly videoHints?: readonly string[];
}

type ApparatusSeedInput = Omit<WorldAtomicSeed, 'apparatus' | 'springs'> & {
  readonly springs?: string;
};

const mat = (seed: ApparatusSeedInput): WorldAtomicSeed => ({
  apparatus: 'mat',
  springs: '매트 체중 저항',
  ...seed,
});

const ref = (seed: Omit<WorldAtomicSeed, 'apparatus'>): WorldAtomicSeed => ({
  apparatus: 'reformer',
  ...seed,
});

const cad = (seed: Omit<WorldAtomicSeed, 'apparatus'>): WorldAtomicSeed => ({
  apparatus: 'cadillac',
  ...seed,
});

const chr = (seed: Omit<WorldAtomicSeed, 'apparatus'>): WorldAtomicSeed => ({
  apparatus: 'chair',
  ...seed,
});

const brl = (seed: ApparatusSeedInput): WorldAtomicSeed => ({
  apparatus: 'barrel',
  springs: '바렐 지지 체중 저항',
  ...seed,
});

